def main():
    assert set(P.keys()) == set(IDS), "id 集与本批不全等: %s" % (set(IDS) ^ set(P.keys()),)
    assert len(P) == 20, "案例数 != 20"
    os.makedirs(OUT, exist_ok=True)
    n = 0
    for cid in IDS:
        rec = {"case_id": cid}
        rec.update(P[cid])
        with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        n += 1
    assert n == 20, "写出文件数 != 20"
    ly = [c for c in IDS if c.startswith("LY-")]
    tc = {k: sum(1 for c in ly if P[c]["trigger"][k]) for k in ("changed_main", "reserve_used", "disputed")}
    print("written:", n)
    print("liuyao_trigger_counts:", json.dumps(tc, ensure_ascii=False))

if __name__ == "__main__":
    main()
